def solve():
    results = []
    for n in range(2, 200):
        if math.gcd(n, 6) == 1:
            valid = True
            # a satisfies floor(n/a) = 2
            # This is equivalent to 2 <= n/a < 3
            # n/3 < a <= n/2
            a_min = math.floor(n/3) + 1
            a_max = math.floor(n/2)

            for a in range(a_min, a_max + 1):
                denominator = n - 2 * a
                if denominator == 0:
                    # Since n is odd, denominator won't be 0
                    continue

                k = n - 2 * a - 1
                # Calculate binomial coefficient (a-1) choose k
                # If k < 0 or k > a-1, C(a-1, k) = 0
                if k < 0 or k > a - 1:
                    numerator = 0
                else:
                    numerator = math.comb(a - 1, k)

                if numerator % denominator != 0:
                    valid = False
                    break

            if valid:
                results.append(n)
    return results

